SyncValidationResult ok_result() {
    return {true, ""};
}

SyncValidationResult fail_result(const std::string& reason) {
    return {false, reason};
}

struct SyncControlledDbAdvanceAbort : std::runtime_error {
    explicit SyncControlledDbAdvanceAbort(const std::string& reason) : std::runtime_error(reason) {}
};

std::string manifest_kind_text(SyncManifestEntryKind kind) {
    switch (kind) {
        case SyncManifestEntryKind::File: return "file";
        case SyncManifestEntryKind::Tombstone: return "tombstone";
    }
    return "unknown";
}

std::string plan_action_text(SyncPlanAction action) {
    switch (action) {
        case SyncPlanAction::Noop: return "noop";
        case SyncPlanAction::FetchRemoteFile: return "fetch_remote_file";
        case SyncPlanAction::PublishLocalFile: return "publish_local_file";
        case SyncPlanAction::ApplyRemoteTombstone: return "apply_remote_tombstone";
        case SyncPlanAction::PublishLocalTombstone: return "publish_local_tombstone";
        case SyncPlanAction::RecordConflict: return "record_conflict";
    }
    return "unknown";
}

std::string lineage_relation_text(SyncLineageRelation relation) {
    switch (relation) {
        case SyncLineageRelation::Equal: return "equal";
        case SyncLineageRelation::LocalNewer: return "local_newer";
        case SyncLineageRelation::RemoteNewer: return "remote_newer";
        case SyncLineageRelation::Concurrent: return "concurrent";
    }
    return "unknown";
}

std::string local_apply_action_text(SyncLocalApplyAction action) {
    switch (action) {
        case SyncLocalApplyAction::Noop: return "noop";
        case SyncLocalApplyAction::StageRemoteFile: return "stage_remote_file";
        case SyncLocalApplyAction::DeleteLocalPath: return "delete_local_path";
        case SyncLocalApplyAction::PreserveConflictCopy: return "preserve_conflict_copy";
        case SyncLocalApplyAction::AdvertiseLocalFile: return "advertise_local_file";
        case SyncLocalApplyAction::AdvertiseLocalTombstone: return "advertise_local_tombstone";
    }
    return "unknown";
}

bool ascii_lower_alnum(char c) {
    return (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9');
}

bool valid_sync_id(const std::string& value) {
    if (value.empty() || value.size() > 128) return false;
    if (!ascii_lower_alnum(value.front()) || !ascii_lower_alnum(value.back())) return false;
    for (unsigned char c : value) {
        if (ascii_lower_alnum(static_cast<char>(c))) continue;
        if (c == '.' || c == '_' || c == '-') continue;
        return false;
    }
    return true;
}

bool reserved_windows_device_name(const std::string& component) {
    std::string stem;
    for (unsigned char c : component) {
        if (c == '.') break;
        stem.push_back(static_cast<char>(std::toupper(c)));
    }
    if (stem == "CON" || stem == "PRN" || stem == "AUX" || stem == "NUL") return true;
    if (stem.size() == 4 && stem.rfind("COM", 0) == 0 && stem[3] >= '1' && stem[3] <= '9') return true;
    if (stem.size() == 4 && stem.rfind("LPT", 0) == 0 && stem[3] >= '1' && stem[3] <= '9') return true;
    return false;
}

bool disallowed_path_byte(unsigned char c) {
    if (c <= 0x1f || c == 0x7f) return true;
    switch (c) {
        case '\\':
        case ':':
        case '*':
        case '?':
        case '"':
        case '<':
        case '>':
        case '|':
            return true;
        default:
            return false;
    }
}


bool valid_utf8(const std::string& input) {
    size_t i = 0;
    while (i < input.size()) {
        const unsigned char c = static_cast<unsigned char>(input[i]);
        if (c <= 0x7f) {
            ++i;
            continue;
        }
        size_t need = 0;
        std::uint32_t codepoint = 0;
        if ((c & 0xe0) == 0xc0) {
            if (c < 0xc2) return false;  // reject overlong two-byte encodings
            need = 1;
            codepoint = c & 0x1f;
        } else if ((c & 0xf0) == 0xe0) {
            need = 2;
            codepoint = c & 0x0f;
        } else if ((c & 0xf8) == 0xf0) {
            need = 3;
            codepoint = c & 0x07;
        } else {
            return false;
        }
        if (i + need >= input.size()) return false;
        for (size_t j = 1; j <= need; ++j) {
            const unsigned char cc = static_cast<unsigned char>(input[i + j]);
            if ((cc & 0xc0) != 0x80) return false;
            codepoint = (codepoint << 6) | (cc & 0x3f);
        }
        if (need == 1 && codepoint < 0x80) return false;
        if (need == 2 && codepoint < 0x800) return false;
        if (need == 3 && codepoint < 0x10000) return false;
        if (codepoint > 0x10ffff) return false;
        if (codepoint >= 0xd800 && codepoint <= 0xdfff) return false;
        i += need + 1;
    }
    return true;
}

std::vector<std::string> split_manifest_path(const std::string& path) {
    std::vector<std::string> parts;
    std::string current;
    for (char c : path) {
        if (c == '/') {
            parts.push_back(current);
            current.clear();
        } else {
            current.push_back(c);
        }
    }
    parts.push_back(current);
    return parts;
}

std::string u64_string(std::uint64_t value) {
    return std::to_string(value);
}

std::string digest_chunks(const std::vector<SyncChunkRange>& chunks) {
    std::string material;
    for (const auto& chunk : chunks) {
        material += length_prefixed_security_tuple("anonsync-sync-chunk-v1", {
            {"offset", u64_string(chunk.offset)},
            {"length", u64_string(chunk.length)},
            {"sha256", chunk.sha256}
        });
    }
    return sha256_hex(material);
}

std::uint64_t sync_manifest_chunk_count(const SyncFolderManifest& manifest) {
    std::uint64_t total = 0;
    for (const auto& entry : manifest.entries) {
        if (entry.chunks.size() > std::numeric_limits<std::uint64_t>::max() - total) {
            throw std::runtime_error("sync manifest chunk count exceeds uint64 range");
        }
        total += static_cast<std::uint64_t>(entry.chunks.size());
    }
    return total;
}

std::string digest_lineage(const std::vector<SyncVersionLineageEntry>& lineage) {
    std::string material;
    for (const auto& entry : lineage) {
        material += length_prefixed_security_tuple("anonsync-sync-lineage-v1", {
            {"device_id", entry.device_id},
            {"counter", u64_string(entry.counter)}
        });
    }
    return sha256_hex(material);
}

std::string digest_manifest_entries(const std::vector<SyncManifestEntry>& entries) {
    std::string material;
    std::uint64_t index = 0;
    for (const auto& entry : entries) {
        material += length_prefixed_security_tuple("anonsync-sync-folder-manifest-entry-digest-v1", {
            {"entry_index", u64_string(index)},
            {"path", entry.path.value},
            {"entry_digest", sync_manifest_entry_digest(entry)}
        });
        ++index;
    }
    return sha256_hex(material);
}

std::string hex_from_digest(const unsigned char* bytes, unsigned int length) {
    std::ostringstream out;
    for (unsigned int i = 0; i < length; ++i) {
        out << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(bytes[i]);
    }
    return out.str();
}

std::string hash_file_and_build_chunks(const fs::path& file_path, std::uint64_t chunk_size,
                                       std::uint64_t& size_bytes, std::vector<SyncChunkRange>& chunks) {
    std::ifstream in(file_path, std::ios::binary);
    if (!in) throw std::runtime_error("could not open sync file for hashing: " + file_path.string());

    MdCtxPtr content_ctx(EVP_MD_CTX_new());
    if (!content_ctx || EVP_DigestInit_ex(content_ctx.get(), EVP_sha256(), nullptr) != 1) {
        throw std::runtime_error("could not initialize sync content digest");
    }

    std::vector<char> buffer(static_cast<size_t>(chunk_size));
    size_bytes = 0;
    chunks.clear();

    while (in) {
        in.read(buffer.data(), static_cast<std::streamsize>(buffer.size()));
        const std::streamsize got = in.gcount();
        if (got <= 0) break;
        const size_t got_size = static_cast<size_t>(got);
        if (EVP_DigestUpdate(content_ctx.get(), buffer.data(), got_size) != 1) {
            throw std::runtime_error("could not update sync content digest");
        }
        if (static_cast<std::uint64_t>(got_size) > std::numeric_limits<std::uint64_t>::max() - size_bytes) {
            throw std::runtime_error("sync file size overflow while hashing");
        }
        chunks.push_back(SyncChunkRange{size_bytes, static_cast<std::uint64_t>(got_size),
                                        sha256_hex(std::string(buffer.data(), got_size))});
        size_bytes += static_cast<std::uint64_t>(got_size);
    }
    if (in.bad()) throw std::runtime_error("could not read sync file while hashing: " + file_path.string());

    unsigned char content_hash[EVP_MAX_MD_SIZE];
    unsigned int content_hash_len = 0;
    if (EVP_DigestFinal_ex(content_ctx.get(), content_hash, &content_hash_len) != 1) {
        throw std::runtime_error("could not finalize sync content digest");
    }
    return hex_from_digest(content_hash, content_hash_len);
}

struct FileContentFingerprint {
    std::uint64_t size_bytes = 0;
    std::string content_sha256;
};

FileContentFingerprint hash_existing_regular_file_content_or_throw(const fs::path& file_path, const std::string& label) {
    std::ifstream in(file_path, std::ios::binary);
    if (!in) throw std::runtime_error(label + " could not be opened for hash verification: " + file_path.string());

    MdCtxPtr content_ctx(EVP_MD_CTX_new());
    if (!content_ctx || EVP_DigestInit_ex(content_ctx.get(), EVP_sha256(), nullptr) != 1) {
        throw std::runtime_error(label + " could not initialize content digest");
    }

    std::array<char, 64 * 1024> buffer{};
    FileContentFingerprint out;
    while (in) {
        in.read(buffer.data(), static_cast<std::streamsize>(buffer.size()));
        const std::streamsize got = in.gcount();
        if (got <= 0) break;
        const size_t got_size = static_cast<size_t>(got);
        if (EVP_DigestUpdate(content_ctx.get(), buffer.data(), got_size) != 1) {
            throw std::runtime_error(label + " could not update content digest");
        }
        if (static_cast<std::uint64_t>(got_size) > std::numeric_limits<std::uint64_t>::max() - out.size_bytes) {
            throw std::runtime_error(label + " size overflow while hashing");
        }
        out.size_bytes += static_cast<std::uint64_t>(got_size);
    }
    if (in.bad()) throw std::runtime_error(label + " could not finish hash verification read");

    unsigned char content_hash[EVP_MAX_MD_SIZE];
    unsigned int content_hash_len = 0;
    if (EVP_DigestFinal_ex(content_ctx.get(), content_hash, &content_hash_len) != 1) {
        throw std::runtime_error(label + " could not finalize content digest");
    }
    out.content_sha256 = hex_from_digest(content_hash, content_hash_len);
    return out;
}

std::string relative_manifest_path_or_throw(const fs::path& root, const fs::path& child) {
    fs::path relative = child.lexically_relative(root);
    const std::string relative_text = relative.generic_string();
    if (relative_text.empty() || relative_text == "." || relative_text == ".." || relative_text.rfind("../", 0) == 0) {
        throw std::runtime_error("could not derive a stable relative sync path for " + child.string());
    }
    return relative_text;
}

fs::path absolute_lexically_normal_path_or_throw(const std::string& raw_path, const std::string& label) {
    if (raw_path.empty()) throw std::invalid_argument(label + " is empty");
    std::error_code ec;
    fs::path absolute = fs::absolute(fs::path(raw_path), ec);
    if (ec) throw std::invalid_argument(label + " could not be resolved: " + ec.message());
    return absolute.lexically_normal();
}

void require_existing_directory_not_symlink_or_throw(const fs::path& path, const std::string& label) {
    std::error_code ec;
    const fs::file_status link_status = fs::symlink_status(path, ec);
    if (ec) throw std::invalid_argument(label + " could not be inspected: " + ec.message());
    if (!fs::exists(link_status)) throw std::invalid_argument(label + " does not exist");
    if (fs::is_symlink(link_status)) throw std::invalid_argument(label + " must not be a symlink");
    if (!fs::is_directory(link_status)) throw std::invalid_argument(label + " must be a directory");
}

void require_existing_path_not_symlink_or_throw(const fs::path& path, const std::string& label) {
    std::error_code ec;
    const fs::file_status link_status = fs::symlink_status(path, ec);
    if (ec) {
        if (ec == std::errc::no_such_file_or_directory) return;
        throw std::invalid_argument(label + " could not be inspected: " + ec.message());
    }
    if (fs::exists(link_status) && fs::is_symlink(link_status)) {
        throw std::invalid_argument(label + " must not be a symlink");
    }
}

void require_absent_or_directory_not_symlink_or_throw(const fs::path& path, const std::string& label) {
    std::error_code ec;
    const fs::file_status link_status = fs::symlink_status(path, ec);
    if (ec) {
        if (ec == std::errc::no_such_file_or_directory) return;
        throw std::invalid_argument(label + " could not be inspected: " + ec.message());
    }
    if (!fs::exists(link_status)) return;
    if (fs::is_symlink(link_status)) throw std::invalid_argument(label + " must not be a symlink");
    if (!fs::is_directory(link_status)) throw std::invalid_argument(label + " must be absent or a directory");
}

bool path_is_self_or_inside(const fs::path& base_path, const fs::path& candidate_path) {
    const fs::path base = base_path.lexically_normal();
    const fs::path candidate = candidate_path.lexically_normal();
    auto base_it = base.begin();
    auto candidate_it = candidate.begin();
    for (; base_it != base.end(); ++base_it, ++candidate_it) {
        if (candidate_it == candidate.end() || *base_it != *candidate_it) return false;
    }
    return true;
}

bool path_is_strictly_inside(const fs::path& base_path, const fs::path& candidate_path) {
    const fs::path base = base_path.lexically_normal();
    const fs::path candidate = candidate_path.lexically_normal();
    return base != candidate && path_is_self_or_inside(base, candidate);
}

bool paths_equal_lexically(const fs::path& left, const fs::path& right) {
    return left.lexically_normal() == right.lexically_normal();
}

void require_no_symlink_ancestors_under_root_or_throw(const fs::path& root_path,
                                                      const fs::path& candidate_path,
                                                      const std::string& label) {
    const fs::path root = root_path.lexically_normal();
    const fs::path candidate = candidate_path.lexically_normal();
    if (!path_is_strictly_inside(root, candidate)) {
        throw std::invalid_argument(label + " must stay below its configured root");
    }

    const fs::path relative = candidate.lexically_relative(root);
    fs::path current = root;
    fs::path parent_relative = relative.parent_path();
    for (const auto& component : parent_relative) {
        if (component == "." || component.empty()) continue;
        current /= component;
        std::error_code ec;
        const fs::file_status status = fs::symlink_status(current, ec);
        if (ec) {
            if (ec == std::errc::no_such_file_or_directory) continue;
            throw std::invalid_argument(label + " ancestor could not be inspected: " + ec.message());
        }
        if (!fs::exists(status)) continue;
        if (fs::is_symlink(status)) throw std::invalid_argument(label + " rejects symlink ancestor: " + current.generic_string());
        if (!fs::is_directory(status)) throw std::invalid_argument(label + " ancestor is not a directory: " + current.generic_string());
    }
}

std::string resolve_normalized_relative_under_root_or_throw(const fs::path& root,
                                                            const NormalizedSyncPath& relative_path,
                                                            const std::string& label) {
    NormalizedSyncPath checked;
    SyncValidationResult validation = normalize_sync_relative_path(relative_path.value, checked);
    if (!validation.ok || checked.value != relative_path.value) {
        throw std::invalid_argument(label + " relative path is not a canonical sync path");
    }
    const fs::path target = (root / fs::path(checked.value)).lexically_normal();
    if (!path_is_strictly_inside(root, target)) {
        throw std::invalid_argument(label + " escaped its configured root");
    }
    return target.generic_string();
}

NormalizedSyncPath append_manifest_path_suffix_or_throw(const NormalizedSyncPath& base_path,
                                                        const std::string& suffix,
                                                        const std::string& label) {
    NormalizedSyncPath out;
    SyncValidationResult validation = normalize_sync_relative_path(base_path.value + suffix, out);
    if (!validation.ok) throw std::invalid_argument(label + " could not be represented as a portable sync path: " + validation.reason);
    return out;
}

SyncManifestEntry canonical_entry_or_throw(const SyncManifestEntry& entry) {
    SyncValidationResult validation = validate_sync_manifest_entry(entry);
    if (!validation.ok) throw std::invalid_argument("invalid sync manifest entry: " + validation.reason);
    return entry;
}

SyncFolderManifest canonical_manifest_or_throw(const SyncFolderManifest& manifest) {
    SyncValidationResult validation = validate_sync_folder_manifest(manifest);
    if (!validation.ok) throw std::invalid_argument("invalid sync folder manifest: " + validation.reason);
    return manifest;
}


SyncLineageRelation compare_lineage_vectors(const std::vector<SyncVersionLineageEntry>& local,
                                            const std::vector<SyncVersionLineageEntry>& remote) {
    std::map<std::string, std::pair<std::uint64_t, std::uint64_t>> counters;
    for (const auto& entry : local) counters[entry.device_id].first = entry.counter;
    for (const auto& entry : remote) counters[entry.device_id].second = entry.counter;

    bool local_greater = false;
    bool remote_greater = false;
    for (const auto& row : counters) {
        const std::uint64_t local_counter = row.second.first;
        const std::uint64_t remote_counter = row.second.second;
        if (local_counter > remote_counter) local_greater = true;
        if (remote_counter > local_counter) remote_greater = true;
    }
    if (local_greater && remote_greater) return SyncLineageRelation::Concurrent;
    if (local_greater) return SyncLineageRelation::LocalNewer;
    if (remote_greater) return SyncLineageRelation::RemoteNewer;
    return SyncLineageRelation::Equal;
}

bool chunk_available_by_hash_and_length(const SyncManifestEntry* local_entry, const SyncChunkRange& remote_chunk) {
    if (local_entry == nullptr || local_entry->kind != SyncManifestEntryKind::File) return false;
    for (const auto& local_chunk : local_entry->chunks) {
        if (local_chunk.length == remote_chunk.length && local_chunk.sha256 == remote_chunk.sha256) return true;
    }
    return false;
}

std::vector<SyncChunkRange> chunks_needed_to_materialize_remote_file(const SyncManifestEntry* local_entry,
                                                                     const SyncManifestEntry& remote_entry) {
    std::vector<SyncChunkRange> needed;
    if (remote_entry.kind != SyncManifestEntryKind::File) return needed;
    for (const auto& remote_chunk : remote_entry.chunks) {
        if (!chunk_available_by_hash_and_length(local_entry, remote_chunk)) needed.push_back(remote_chunk);
    }
    return needed;
}

std::string digest_or_empty(const SyncManifestEntry* entry) {
    return entry == nullptr ? std::string() : sync_manifest_entry_digest(*entry);
}

std::string version_digest_or_empty(const SyncManifestEntry* entry) {
    return entry == nullptr ? std::string() : sync_manifest_entry_version_digest(*entry);
}

std::string stable_conflict_set_id(const std::string& folder_id,
                                   const std::string& path,
                                   const std::string& local_version_digest,
                                   const std::string& remote_version_digest) {
    const std::string material = length_prefixed_security_tuple("anonsync-sync-conflict-set-v1", {
        {"folder_id", folder_id},
        {"path", path},
        {"local_version_digest", local_version_digest},
        {"remote_version_digest", remote_version_digest}
    });
    return "conflict-" + sha256_hex(material).substr(0, 32);
}

SyncManifestPlanEntry make_plan_entry(const std::string& folder_id,
                                      const NormalizedSyncPath& path,
                                      const SyncManifestEntry* local_entry,
                                      const SyncManifestEntry* remote_entry,
                                      SyncLineageRelation relation,
                                      SyncPlanAction action,
                                      const std::string& reason) {
    SyncManifestPlanEntry plan;
    plan.path = path;
    plan.action = action;
    plan.lineage_relation = relation;
    plan.local_entry_present = local_entry != nullptr;
    plan.remote_entry_present = remote_entry != nullptr;
    if (local_entry != nullptr) {
        plan.local_entry_kind = local_entry->kind;
        plan.local_size_bytes = local_entry->size_bytes;
        plan.local_content_sha256 = local_entry->content_sha256;
    }
    if (remote_entry != nullptr) {
        plan.remote_entry_kind = remote_entry->kind;
        plan.remote_size_bytes = remote_entry->size_bytes;
        plan.remote_content_sha256 = remote_entry->content_sha256;
    }
    plan.local_entry_digest = digest_or_empty(local_entry);
    plan.remote_entry_digest = digest_or_empty(remote_entry);
    plan.local_version_digest = version_digest_or_empty(local_entry);
    plan.remote_version_digest = version_digest_or_empty(remote_entry);
    plan.reason = reason;
    if ((action == SyncPlanAction::FetchRemoteFile || action == SyncPlanAction::RecordConflict) &&
        remote_entry != nullptr && remote_entry->kind == SyncManifestEntryKind::File) {
        plan.needed_chunks = chunks_needed_to_materialize_remote_file(local_entry, *remote_entry);
    }
    if (action == SyncPlanAction::RecordConflict) {
        plan.conflict_set_id = stable_conflict_set_id(folder_id, path.value, plan.local_version_digest, plan.remote_version_digest);
    }
    return plan;
}

bool digest_field_ok_or_empty(const std::string& value) {
    return value.empty() || is_lowercase_sha256_hex(value);
}

SyncValidationResult validate_needed_chunks(const std::vector<SyncChunkRange>& chunks) {
    for (const auto& chunk : chunks) {
        if (chunk.length == 0) return fail_result("needed chunk length must be positive");
        if (!is_lowercase_sha256_hex(chunk.sha256)) return fail_result("needed chunk requires lowercase sha256 hash");
    }
    return ok_result();
}

SyncValidationResult validate_plan_entry_shape(const SyncManifestPlanEntry& entry) {
    NormalizedSyncPath normalized;
    SyncValidationResult path_result = normalize_sync_relative_path(entry.path.value, normalized);
    if (!path_result.ok) return fail_result("plan path invalid: " + path_result.reason);
    if (normalized.value != entry.path.value) return fail_result("plan path is not canonical");
    if (plan_action_text(entry.action) == "unknown") return fail_result("plan entry has unknown action");
    if (lineage_relation_text(entry.lineage_relation) == "unknown") return fail_result("plan entry has unknown lineage relation");
    if (!digest_field_ok_or_empty(entry.local_entry_digest) ||
        !digest_field_ok_or_empty(entry.remote_entry_digest) ||
        !digest_field_ok_or_empty(entry.local_version_digest) ||
        !digest_field_ok_or_empty(entry.remote_version_digest)) {
        return fail_result("plan entry digest fields must be lowercase sha256 or empty");
    }
    if (entry.local_entry_present) {
        if (entry.local_entry_digest.empty() || entry.local_version_digest.empty()) return fail_result("local plan entry is present without local digest evidence");
        if (entry.local_entry_kind == SyncManifestEntryKind::File) {
            if (!is_lowercase_sha256_hex(entry.local_content_sha256)) return fail_result("local file plan entry requires content sha256 evidence");
        } else if (!entry.local_content_sha256.empty() || entry.local_size_bytes != 0) {
            return fail_result("local tombstone plan entry must not carry file content evidence");
        }
    } else if (!entry.local_entry_digest.empty() || !entry.local_version_digest.empty() ||
               !entry.local_content_sha256.empty() || entry.local_size_bytes != 0) {
        return fail_result("local plan entry evidence exists without presence bit");
    }
    if (entry.remote_entry_present) {
        if (entry.remote_entry_digest.empty() || entry.remote_version_digest.empty()) return fail_result("remote plan entry is present without remote digest evidence");
        if (entry.remote_entry_kind == SyncManifestEntryKind::File) {
            if (!is_lowercase_sha256_hex(entry.remote_content_sha256)) return fail_result("remote file plan entry requires content sha256 evidence");
        } else if (!entry.remote_content_sha256.empty() || entry.remote_size_bytes != 0) {
            return fail_result("remote tombstone plan entry must not carry file content evidence");
        }
    } else if (!entry.remote_entry_digest.empty() || !entry.remote_version_digest.empty() ||
               !entry.remote_content_sha256.empty() || entry.remote_size_bytes != 0) {
        return fail_result("remote plan entry evidence exists without presence bit");
    }
    if (!entry.conflict_set_id.empty() && !valid_sync_id(entry.conflict_set_id)) {
        return fail_result("plan entry conflict_set_id must be empty or a lowercase portable sync id");
    }
    SyncValidationResult chunks_result = validate_needed_chunks(entry.needed_chunks);
    if (!chunks_result.ok) return chunks_result;

    switch (entry.action) {
        case SyncPlanAction::Noop:
            if (!entry.local_entry_present || !entry.remote_entry_present) return fail_result("noop requires both local and remote entries");
            if (!entry.conflict_set_id.empty() || !entry.needed_chunks.empty()) return fail_result("noop must not carry conflict or chunk work");
            break;
        case SyncPlanAction::FetchRemoteFile:
            if (!entry.remote_entry_present || entry.remote_entry_kind != SyncManifestEntryKind::File) return fail_result("fetch requires a remote file entry");
            break;
        case SyncPlanAction::ApplyRemoteTombstone:
            if (!entry.remote_entry_present || entry.remote_entry_kind != SyncManifestEntryKind::Tombstone) return fail_result("apply tombstone requires a remote tombstone entry");
            if (!entry.needed_chunks.empty()) return fail_result("apply tombstone must not carry chunk work");
            break;
        case SyncPlanAction::PublishLocalFile:
            if (!entry.local_entry_present || entry.local_entry_kind != SyncManifestEntryKind::File) return fail_result("publish file requires a local file entry");
            if (!entry.needed_chunks.empty()) return fail_result("publish file must not carry inbound chunk work");
            break;
        case SyncPlanAction::PublishLocalTombstone:
            if (!entry.local_entry_present || entry.local_entry_kind != SyncManifestEntryKind::Tombstone) return fail_result("publish tombstone requires a local tombstone entry");
            if (!entry.needed_chunks.empty()) return fail_result("publish tombstone must not carry inbound chunk work");
            break;
        case SyncPlanAction::RecordConflict:
            if (!entry.local_entry_present || !entry.remote_entry_present) return fail_result("conflict requires both local and remote entries");
            if (entry.conflict_set_id.empty()) return fail_result("conflict requires a stable conflict_set_id");
            if (entry.remote_entry_kind != SyncManifestEntryKind::File && !entry.needed_chunks.empty()) {
                return fail_result("conflict tombstone must not carry remote chunk work");
            }
            break;
    }
    return ok_result();
}

SyncValidationResult validate_manifest_diff_plan_shape(const SyncManifestDiffPlan& plan) {
    if (!valid_sync_id(plan.folder_id)) return fail_result("diff plan folder_id must be lowercase portable sync id");
    if (!valid_sync_id(plan.local_device_id)) return fail_result("diff plan local_device_id must be lowercase portable sync id");
    if (!valid_sync_id(plan.remote_device_id)) return fail_result("diff plan remote_device_id must be lowercase portable sync id");
    if (plan.local_device_id == plan.remote_device_id) return fail_result("diff plan local and remote device ids must differ");
    if (!is_lowercase_sha256_hex(plan.local_manifest_digest) || !is_lowercase_sha256_hex(plan.remote_manifest_digest)) {
        return fail_result("diff plan manifest digests must be lowercase sha256");
    }
    std::string previous_path;
    for (const auto& entry : plan.entries) {
        SyncValidationResult entry_result = validate_plan_entry_shape(entry);
        if (!entry_result.ok) return fail_result("diff plan entry invalid: " + entry_result.reason);
        if (!previous_path.empty() && entry.path.value <= previous_path) return fail_result("diff plan entries must be sorted by unique path");
        previous_path = entry.path.value;
    }
    return ok_result();
}

SyncLocalApplyAction local_apply_action_for_plan_action(SyncPlanAction action) {
    switch (action) {
        case SyncPlanAction::Noop: return SyncLocalApplyAction::Noop;
        case SyncPlanAction::FetchRemoteFile: return SyncLocalApplyAction::StageRemoteFile;
        case SyncPlanAction::ApplyRemoteTombstone: return SyncLocalApplyAction::DeleteLocalPath;
        case SyncPlanAction::RecordConflict: return SyncLocalApplyAction::PreserveConflictCopy;
        case SyncPlanAction::PublishLocalFile: return SyncLocalApplyAction::AdvertiseLocalFile;
        case SyncPlanAction::PublishLocalTombstone: return SyncLocalApplyAction::AdvertiseLocalTombstone;
    }
    throw std::invalid_argument("cannot map unknown sync plan action to local apply action");
}

std::string local_apply_idempotency_key(const SyncManifestDiffPlan& diff_plan,
                                        const SyncLocalApplyPlanEntry& entry) {
    const std::string material = length_prefixed_security_tuple("anonsync-sync-local-apply-intent-v1", {
        {"folder_id", diff_plan.folder_id},
        {"local_device_id", diff_plan.local_device_id},
        {"remote_device_id", diff_plan.remote_device_id},
        {"local_manifest_digest", diff_plan.local_manifest_digest},
        {"remote_manifest_digest", diff_plan.remote_manifest_digest},
        {"path", entry.path.value},
        {"source_action", plan_action_text(entry.source_action)},
        {"local_action", local_apply_action_text(entry.local_action)},
        {"local_entry_present", entry.local_entry_present ? "true" : "false"},
        {"remote_entry_present", entry.remote_entry_present ? "true" : "false"},
        {"local_entry_kind", entry.local_entry_present ? manifest_kind_text(entry.local_entry_kind) : "absent"},
        {"remote_entry_kind", entry.remote_entry_present ? manifest_kind_text(entry.remote_entry_kind) : "absent"},
        {"local_size_bytes", u64_string(entry.local_size_bytes)},
        {"remote_size_bytes", u64_string(entry.remote_size_bytes)},
        {"local_content_sha256", entry.local_content_sha256},
        {"remote_content_sha256", entry.remote_content_sha256},
        {"local_entry_digest", entry.local_entry_digest},
        {"remote_entry_digest", entry.remote_entry_digest},
        {"local_version_digest", entry.local_version_digest},
        {"remote_version_digest", entry.remote_version_digest},
        {"conflict_set_id", entry.conflict_set_id}
    });
    return "sync-local-apply:v1:" + sha256_hex(material);
}

