std::string sync_session_checkpoint_idempotency_key(const SyncFakePeerFileFetchSessionOptions& run_options,
                                                    const SyncFakePeerFileFetchSessionResult& session_result,
                                                    const std::string& session_id,
                                                    const std::string& source_manifest_digest,
                                                    const std::string& destination_before_manifest_digest,
                                                    const std::string& destination_after_manifest_digest) {
    const std::string material = length_prefixed_security_tuple("anonsync-sync-session-checkpoint-v1", {
        {"session_id", session_id},
        {"folder_id", run_options.folder_id},
        {"source_device_id", run_options.source_device_id},
        {"destination_device_id", run_options.destination_device_id},
        {"peer_id", run_options.peer_id},
        {"peer_session_id", run_options.peer_session_id},
        {"source_manifest_digest", source_manifest_digest},
        {"destination_manifest_before_digest", destination_before_manifest_digest},
        {"destination_manifest_after_digest", destination_after_manifest_digest},
        {"source_content_digest", session_result.source_content_digest},
        {"destination_content_digest", session_result.destination_content_digest},
        {"apply_entries_considered", u64_string(session_result.apply_entries_considered)},
        {"files_materialized", u64_string(session_result.files_materialized)},
        {"transfer_rounds", u64_string(session_result.transfer_rounds)},
        {"chunks_written", u64_string(session_result.chunks_written)},
        {"receipts_reused", u64_string(session_result.receipts_reused)},
        {"cleanup_receipts_removed", u64_string(session_result.cleanup_receipts_removed)},
    });
    return "sync-session-checkpoint:v1:" + sha256_hex(material);
}

void validate_fake_session_result_for_checkpoint_or_throw(const SyncFakePeerFileFetchSessionOptions& run_options,
                                                          const SyncFakePeerFileFetchSessionResult& session_result,
                                                          const SyncSessionCheckpointOptions& checkpoint_options) {
    if (!valid_sync_id(run_options.folder_id) || !valid_sync_id(run_options.source_device_id) ||
        !valid_sync_id(run_options.destination_device_id) || !valid_sync_id(run_options.peer_id) ||
        !valid_sync_id(run_options.peer_session_id)) {
        throw std::runtime_error("sync session checkpoint requires valid run identity fields");
    }
    if (!valid_sync_id(checkpoint_options.session_id)) {
        throw std::runtime_error("sync session checkpoint session_id must be lowercase portable sync id");
    }
    if (checkpoint_options.require_converged_session && !session_result.content_converged) {
        throw std::runtime_error("sync session checkpoint requires a converged fake peer session result");
    }
    if (session_result.source_manifest.folder_id != run_options.folder_id ||
        session_result.destination_manifest_before.folder_id != run_options.folder_id ||
        session_result.destination_manifest_after.folder_id != run_options.folder_id ||
        session_result.diff_plan.folder_id != run_options.folder_id ||
        session_result.apply_plan.folder_id != run_options.folder_id) {
        throw std::runtime_error("sync session checkpoint folder identity mismatch");
    }
    if (session_result.source_manifest.device_id != run_options.source_device_id ||
        session_result.destination_manifest_before.device_id != run_options.destination_device_id ||
        session_result.destination_manifest_after.device_id != run_options.destination_device_id ||
        session_result.diff_plan.remote_device_id != run_options.source_device_id ||
        session_result.diff_plan.local_device_id != run_options.destination_device_id ||
        session_result.apply_plan.remote_device_id != run_options.source_device_id ||
        session_result.apply_plan.local_device_id != run_options.destination_device_id) {
        throw std::runtime_error("sync session checkpoint device identity mismatch");
    }
    if (session_result.files_materialized != static_cast<std::uint64_t>(session_result.files.size())) {
        throw std::runtime_error("sync session checkpoint materialized file count mismatch");
    }
    std::uint64_t file_rounds = 0;
    std::uint64_t file_chunks = 0;
    std::uint64_t file_reused = 0;
    std::uint64_t file_bytes = 0;
    std::uint64_t file_cleanup_receipts = 0;
    std::uint64_t file_cleanup_dirs = 0;
    for (const auto& file : session_result.files) {
        if (!file.materialized) throw std::runtime_error("sync session checkpoint file result is not materialized");
        if (file.source_content_sha256.empty() || file.source_content_sha256 != file.destination_content_sha256) {
            throw std::runtime_error("sync session checkpoint file result content hash mismatch");
        }
        if (checkpoint_options.require_committed_cleanup && run_options.cleanup_staged_transfer_artifacts_after_materialization && !file.staging_artifacts_cleaned) {
            throw std::runtime_error("sync session checkpoint requires committed cleanup evidence for every materialized file");
        }
        file_rounds += file.transfer_rounds;
        file_chunks += file.chunks_written;
        file_reused += file.receipts_reused;
        file_bytes += file.bytes_materialized;
        file_cleanup_receipts += file.cleanup_receipts_removed;
        file_cleanup_dirs += file.cleanup_directories_removed;
    }
    if (file_rounds != session_result.transfer_rounds || file_chunks != session_result.chunks_written ||
        file_reused != session_result.receipts_reused || file_bytes != session_result.bytes_materialized ||
        file_cleanup_receipts != session_result.cleanup_receipts_removed ||
        file_cleanup_dirs != session_result.cleanup_directories_removed) {
        throw std::runtime_error("sync session checkpoint aggregate file evidence mismatch");
    }
}

