std::string checkpoint_resume_chunk_receipt_material_or_throw(const std::string& remote_entry_digest,
                                                              const std::string& remote_version_digest,
                                                              const std::string& apply_intent_key,
                                                              const NormalizedSyncPath& path,
                                                              const std::string& staging_path,
                                                              const SyncChunkRange& chunk) {
    if (!is_lowercase_sha256_hex(remote_entry_digest) || !is_lowercase_sha256_hex(remote_version_digest)) {
        throw std::runtime_error("sync session checkpoint resume chunk receipt requires digest evidence");
    }
    if (!apply_intent_key.starts_with("sync-local-apply:v1:")) {
        throw std::runtime_error("sync session checkpoint resume chunk receipt requires apply intent evidence");
    }
    if (!is_lowercase_sha256_hex(chunk.sha256)) {
        throw std::runtime_error("sync session checkpoint resume chunk receipt requires chunk hash evidence");
    }
    return length_prefixed_security_tuple("anonsync-sync-staged-chunk-receipt-v1", {
        {"remote_entry_digest", remote_entry_digest},
        {"remote_version_digest", remote_version_digest},
        {"apply_intent_key", apply_intent_key},
        {"path", path.value},
        {"staging_path", staging_path},
        {"offset", u64_string(chunk.offset)},
        {"length", u64_string(chunk.length)},
        {"chunk_sha256", chunk.sha256}
    });
}

std::string checkpoint_resume_chunk_receipt_idempotency_key_or_throw(const std::string& remote_entry_digest,
                                                                     const std::string& remote_version_digest,
                                                                     const std::string& apply_intent_key,
                                                                     const NormalizedSyncPath& path,
                                                                     const std::string& staging_path,
                                                                     const SyncChunkRange& chunk) {
    return "sync-chunk-receipt:v1:" + sha256_hex(checkpoint_resume_chunk_receipt_material_or_throw(remote_entry_digest,
                                                                                                    remote_version_digest,
                                                                                                    apply_intent_key,
                                                                                                    path,
                                                                                                    staging_path,
                                                                                                    chunk));
}

std::string resume_transfer_source_action_string_or_throw(SyncSessionCheckpointResumeActionKind action) {
    if (action == SyncSessionCheckpointResumeActionKind::ResumeTransfer) return "resume-transfer";
    if (action == SyncSessionCheckpointResumeActionKind::RetryTransfer) return "retry-transfer";
    throw std::runtime_error("sync session checkpoint resume transfer workorder source action must be ResumeTransfer or RetryTransfer");
}

