            sqlite_bind_text_or_throw(update_stmt.stmt, 4, owner_lock_id, "daemon owner lock release id update");
            sqlite_step_done_or_throw(update_stmt.stmt, "sync session checkpoint resume transfer daemon owner lock could not release row");
