                out.startup_sidecar_recovery_archived_checkpoint_migration_backfill_required = checkpoint_evidence.archived_checkpoint_migration_backfill_required;
                out.startup_sidecar_recovery_archived_checkpoint_migration_backfill_blocked_missing_lineage = checkpoint_evidence.archived_checkpoint_migration_backfill_blocked_missing_lineage;
