                sqlite_bind_u64_or_throw(timed_stmt.stmt, 4, options.scheduler_now_epoch, "sync session checkpoint operator status retryable expired now 1");
                sqlite_bind_u64_or_throw(timed_stmt.stmt, 5, options.scheduler_now_epoch, "sync session checkpoint operator status retryable expired now 2");
