                sqlite_bind_u64_or_throw(timed_stmt.stmt, 7, options.scheduler_now_epoch, "sync session checkpoint operator status cooling expired now 2");
                sqlite_bind_text_or_throw(timed_stmt.stmt, 8, options.session_id, "sync session checkpoint operator status timed workorder metrics session");
                const int timed_rc = sqlite3_step(timed_stmt.stmt);
                if (timed_rc != SQLITE_ROW) throw std::runtime_error("sync session checkpoint operator status timed workorder metrics returned no row");
                out.live_claimed_workorder_rows = sqlite_column_u64_or_throw(timed_stmt.stmt, 0, "sync session checkpoint operator status live claimed workorders");
                out.expired_claimed_workorder_rows = sqlite_column_u64_or_throw(timed_stmt.stmt, 1, "sync session checkpoint operator status expired claimed workorders");
